-- BAĞ ENVANTERİ (Paket 0) — SALT OKUR (28 Kasım). Hiçbir şey yazmaz, hiçbir şeyi onarmaz.
-- Bölümler: A yetim kayıt (kimlik var, üst kayıt yok) · B boşalmış bağ · C yanlış üst kayıt (iki bağ birbirini tutmuyor) ·
--           D eski tabloların kullanımı · E ada bağlı kayıtların hacmi ve eşleşme durumu · F belirsizlik (aynı ada birden çok kimlik)
-- Sütunlar: toplam = bakılan kayıt · sorunlu = hedefe uymayan kayıt (0 beklenir; E ve D bölümlerinde bilgi amaçlı).
with
vr as (select v.urun_id, v.renk, v.beden, public.stk_nrm(v.renk) rn, public.stk_nrm(v.beden) bn from public.varyantlar v),
rc as (select z.id urun_id, r from public.urunler z, jsonb_array_elements(case when jsonb_typeof(z.recete) = 'array' then z.recete else '[]'::jsonb end) r),
ps as (select p ->> 'ad' ad from public.tanimlar t, jsonb_array_elements(coalesce(t.veri -> 'prosesler', '[]'::jsonb)) p where t.id = 'tekil'),
e(bolum, kontrol, toplam, sorunlu) as (
  -- A · yetim
            select 'A', 'cari hareketi → cari (car_hareket.cari_id)', count(*), count(*) filter (where not exists (select 1 from public.cariler c where c.id = h.cari_id)) from public.car_hareket h
  union all select 'A', 'cari hareketi → üretim (car_hareket.uretim_id; silinmiş üretim ayrı sayılır)', count(*) filter (where h.uretim_id is not null),
                   count(*) filter (where h.uretim_id is not null and not exists (select 1 from public.uretim u where u.id = h.uretim_id)) from public.car_hareket h
  union all select 'A', 'fiş → cari (stk_fis.cari_id)', count(*) filter (where f.cari_id is not null), count(*) filter (where f.cari_id is not null and not exists (select 1 from public.cariler c where c.id = f.cari_id)) from public.stk_fis f
  union all select 'A', 'fiş → sipariş (stk_fis.siparis_id)', count(*) filter (where f.siparis_id is not null), count(*) filter (where f.siparis_id is not null and not exists (select 1 from public.siparisler s where s.id = f.siparis_id)) from public.stk_fis f
  union all select 'A', 'fiş → üretim (stk_fis.uretim_id)', count(*) filter (where f.uretim_id is not null), count(*) filter (where f.uretim_id is not null and not exists (select 1 from public.uretim u where u.id = f.uretim_id)) from public.stk_fis f
  union all select 'A', 'fiş → kasa hesabı (stk_fis.kasa_hesap_id)', count(*) filter (where f.kasa_hesap_id is not null), count(*) filter (where f.kasa_hesap_id is not null and not exists (select 1 from public.kas_hesap k where k.id = f.kasa_hesap_id)) from public.stk_fis f
  union all select 'A', 'stok hareketi → ürün (stk_hareket.urun_id)', count(*), count(*) filter (where not exists (select 1 from public.urunler u where u.id = h.urun_id)) from public.stk_hareket h
  union all select 'A', 'stok hareketi → sipariş (stk_hareket.siparis_id)', count(*) filter (where h.siparis_id is not null), count(*) filter (where h.siparis_id is not null and not exists (select 1 from public.siparisler s where s.id = h.siparis_id)) from public.stk_hareket h
  union all select 'A', 'stok hareketi → cari (stk_hareket.cari_id)', count(*) filter (where h.cari_id is not null), count(*) filter (where h.cari_id is not null and not exists (select 1 from public.cariler c where c.id = h.cari_id)) from public.stk_hareket h
  union all select 'A', 'stok hareketi → üretim (stk_hareket.uretim_id)', count(*) filter (where h.uretim_id is not null), count(*) filter (where h.uretim_id is not null and not exists (select 1 from public.uretim u where u.id = h.uretim_id)) from public.stk_hareket h
  union all select 'A', 'kasa hareketi → kasa hesabı (kas_hareket.hesap_id)', count(*), count(*) filter (where not exists (select 1 from public.kas_hesap k where k.id = h.hesap_id)) from public.kas_hareket h
  union all select 'A', 'varyant → ürün (stk_varyant.urun_id)', count(*), count(*) filter (where not exists (select 1 from public.urunler u where u.id = v.urun_id)) from public.stk_varyant v
  union all select 'A', 'üretim → rezervasyon siparişi (uretim.rezervasyon_siparis_id)', count(*) filter (where u.rezervasyon_siparis_id is not null), count(*) filter (where u.rezervasyon_siparis_id is not null and not exists (select 1 from public.siparisler s where s.id = u.rezervasyon_siparis_id)) from public.uretim u
  union all select 'A', 'site talebi → cari (site_talepleri.cari_id)', count(*), count(*) filter (where not exists (select 1 from public.cariler c where c.id = t.cari_id)) from public.site_talepleri t
  union all select 'A', 'site hesabı → cari (site_hesaplari.cari_id)', count(*), count(*) filter (where not exists (select 1 from public.cariler c where c.id = t.cari_id)) from public.site_hesaplari t
  -- B · boşalmış bağ (üst kayıt silinince SET NULL)
  union all select 'B', 'carisi boş sipariş (siparisler.cari_id)', count(*), count(*) filter (where s.cari_id is null) from public.siparisler s
  union all select 'B', 'ürünü boş sipariş kalemi (siparis_kalemleri.urun_id)', count(*), count(*) filter (where k.urun_id is null) from public.siparis_kalemleri k
  union all select 'B', 'ürünü boş üretim (uretim.urun_id)', count(*), count(*) filter (where u.urun_id is null) from public.uretim u
  union all select 'B', 'kişisi boş, verilmiş üretim ataması (uretim_atamalari.personel_id)', count(*) filter (where a.verildi_mi), count(*) filter (where a.verildi_mi and a.personel_id is null) from public.uretim_atamalari a
  -- C · yanlış üst kayıt
  union all select 'C', 'stok hareketinin siparişi ≠ kaleminin siparişi', count(*) filter (where h.kalem_id is not null), count(*) filter (where h.kalem_id is not null and exists (select 1 from public.siparis_kalemleri k where k.id = h.kalem_id and k.siparis_id is distinct from h.siparis_id)) from public.stk_hareket h
  union all select 'C', 'stok hareketinin ürünü ≠ varyantının ürünü', count(*), count(*) filter (where exists (select 1 from public.stk_varyant v where v.id = h.varyant_id and v.urun_id is distinct from h.urun_id)) from public.stk_hareket h
  union all select 'C', 'stok hareketinin ürünü ≠ kaleminin ürünü', count(*) filter (where h.kalem_id is not null), count(*) filter (where h.kalem_id is not null and exists (select 1 from public.siparis_kalemleri k where k.id = h.kalem_id and k.urun_id is distinct from h.urun_id)) from public.stk_hareket h
  union all select 'C', 'stok hareketinin carisi ≠ fişinin carisi (iptal edilmemiş)', count(*) filter (where h.cari_id is not null and not coalesce(h.iptal, false)), count(*) filter (where h.cari_id is not null and not coalesce(h.iptal, false) and exists (select 1 from public.stk_fis f where f.id = h.fis_id and f.cari_id is not null and f.cari_id <> h.cari_id)) from public.stk_hareket h
  union all select 'C', 'cari hareketinin carisi ≠ fişinin carisi (iptal edilmemiş)', count(*) filter (where h.fis_id is not null and not coalesce(h.iptal, false)), count(*) filter (where h.fis_id is not null and not coalesce(h.iptal, false) and exists (select 1 from public.stk_fis f where f.id = h.fis_id and f.cari_id is not null and f.cari_id <> h.cari_id)) from public.car_hareket h
  union all select 'C', 'fişin carisi ≠ siparişinin carisi (iptal edilmemiş fiş)', count(*) filter (where f.siparis_id is not null and f.cari_id is not null and not coalesce(f.iptal, false)), count(*) filter (where f.siparis_id is not null and f.cari_id is not null and not coalesce(f.iptal, false) and exists (select 1 from public.siparisler s where s.id = f.siparis_id and s.cari_id is distinct from f.cari_id)) from public.stk_fis f
  union all select 'C', 'kasa hareketinin hesabı ≠ fişinin kasa hesabı (iptal edilmemiş)', count(*) filter (where h.fis_id is not null and not coalesce(h.iptal, false)), count(*) filter (where h.fis_id is not null and not coalesce(h.iptal, false) and exists (select 1 from public.stk_fis f where f.id = h.fis_id and f.kasa_hesap_id is not null and f.kasa_hesap_id <> h.hesap_id)) from public.kas_hareket h
  -- D · eski tablolar (topluca silme kuralı taşıyanlar): satır varsa kural önemlidir
  union all select 'D', 'eski hesaplar tablosunda satır (sorunlu = satır sayısı)', count(*), count(*) from public.hesaplar
  union all select 'D', 'eski hesap_hareketleri tablosunda satır', count(*), count(*) from public.hesap_hareketleri
  union all select 'D', 'eski cekler tablosunda satır', count(*), count(*) from public.cekler
  union all select 'D', 'silinen arşivindeki kayıt (bilgi)', count(*), 0 from public.silinen_arsiv
  -- E · ada bağlı kayıtlar: sorunlu = BİREBİR eşleşmeyen
  union all select 'E', 'sipariş kalemi: renk + beden, ürününün bir varyantıyla BİREBİR aynı değil', count(*), count(*) filter (where not exists (select 1 from vr where vr.urun_id = k.urun_id and vr.renk = k.renk and vr.beden = k.beden)) from public.siparis_kalemleri k where k.urun_id is not null
  union all select 'E', '  … bunlardan yalnız harf / boşluk farkıyla eşleşen', count(*), count(*) filter (where exists (select 1 from vr where vr.urun_id = k.urun_id and vr.rn = public.stk_nrm(k.renk) and vr.bn = public.stk_nrm(k.beden)))
     from public.siparis_kalemleri k where k.urun_id is not null and not exists (select 1 from vr where vr.urun_id = k.urun_id and vr.renk = k.renk and vr.beden = k.beden)
  union all select 'E', 'üretim: renk, ürününün bir varyant rengiyle BİREBİR aynı değil', count(*), count(*) filter (where not exists (select 1 from vr where vr.urun_id = u.urun_id and vr.renk = u.renk)) from public.uretim u where u.urun_id is not null and coalesce(u.renk, '') <> ''
  union all select 'E', 'rezervasyon: renk + beden, ürününün bir varyantıyla BİREBİR aynı değil', count(*), count(*) filter (where not exists (select 1 from vr where vr.urun_id = z.urun_id and vr.renk = z.renk and vr.beden = z.beden)) from public.stok_rezervasyonlari z
  union all select 'E', 'reçete satırı: model rengi (mamulRenk), ürününün bir varyant rengiyle BİREBİR aynı değil', count(*), count(*) filter (where not exists (select 1 from vr where vr.urun_id = rc.urun_id and vr.renk = rc.r ->> 'mamulRenk')) from rc where coalesce(rc.r ->> 'mamulRenk', '') <> ''
  union all select 'E', 'reçete satırı: hammadde rengi dolu ama renk kimliği (renkId) yok', count(*) filter (where coalesce(rc.r ->> 'renk', '') not in ('', 'Standart')), count(*) filter (where coalesce(rc.r ->> 'renk', '') not in ('', 'Standart') and coalesce(rc.r ->> 'renkId', '') = '') from rc
  union all select 'E', 'reçete satırı: renk kimliği var ama kimlikteki ad ile satırdaki ad ÇELİŞİYOR', count(*) filter (where coalesce(rc.r ->> 'renkId', '') <> ''), count(*) filter (where coalesce(rc.r ->> 'renkId', '') <> '' and not exists (select 1 from public.stk_renk s where s.id = rc.r ->> 'renkId' and public.stk_nrm(s.ad) = public.stk_nrm(rc.r ->> 'renk'))) from rc
  union all select 'E', 'üretim ataması: proses adı Tanımlar''daki bir prosesle BİREBİR aynı değil', count(*), count(*) filter (where not exists (select 1 from ps where ps.ad = a.proses)) from public.uretim_atamalari a
  union all select 'E', 'ürün proses ücreti: anahtar (proses adı) Tanımlar''da BİREBİR yok', count(*), count(*) filter (where not exists (select 1 from ps where ps.ad = x.key)) from public.urunler z, jsonb_each(case when jsonb_typeof(z.proses_ucretleri) = 'object' then z.proses_ucretleri else '{}'::jsonb end) x
  union all select 'E', 'carinin bağlı prosesi: ad Tanımlar''da BİREBİR yok', count(*), count(*) filter (where not exists (select 1 from ps where ps.ad = x)) from public.cariler c, jsonb_array_elements_text(case when jsonb_typeof(c.bagli_prosesler) = 'array' then c.bagli_prosesler else '[]'::jsonb end) x
  union all select 'E', 'özel tipli cari (ek.altTip dolu); sorunlu = tipi tam "Fasoncu" olan (ödeme yönü ada bağlı)', count(*) filter (where coalesce(c.ek ->> 'altTip', '') <> ''), count(*) filter (where c.ek ->> 'altTip' = 'Fasoncu') from public.cariler c
  union all select 'E', '  … adı "fason" içeren ama tam "Fasoncu" OLMAYAN tipte cari (fasoncu sayılmıyor)', count(*) filter (where coalesce(c.ek ->> 'altTip', '') <> ''), count(*) filter (where c.ek ->> 'altTip' ilike '%fason%' and c.ek ->> 'altTip' <> 'Fasoncu') from public.cariler c
  union all select 'E', 'cari: ana tipi dört sabit tipten (Müşteri, Tedarikçi, Personel, Her İkisi) biri olmayan', count(*), count(*) filter (where c.tip not in ('Müşteri', 'Tedarikçi', 'Personel', 'Her İkisi')) from public.cariler c
  union all select 'E', 'cari hareketi: ürün adı dolu (ürün kimliği yok); sorunlu = adı hiçbir ürünle BİREBİR eşleşmeyen', count(*) filter (where coalesce(h.urun_ad, '') <> ''), count(*) filter (where coalesce(h.urun_ad, '') <> '' and not exists (select 1 from public.urunler u where u.ad = h.urun_ad)) from public.car_hareket h
  -- F · belirsizlik
  union all select 'F', 'etkin renk / model rengi: aynı ada (harf duyarsız) birden çok kimlik', (select count(*) from public.stk_renk where aktif), count(*) from (select 1 from public.stk_renk where aktif group by public.stk_nrm(ad) having count(*) > 1) x
  union all select 'F', 'etkin ölçü: aynı ada birden çok kimlik', (select count(*) from public.stk_olcu where aktif), count(*) from (select 1 from public.stk_olcu where aktif group by public.stk_nrm(ad) having count(*) > 1) x
  union all select 'F', 'Tanımlar''da proses: aynı ada birden çok kayıt', (select count(*) from ps), count(*) from (select 1 from ps group by public.stk_nrm(ad) having count(*) > 1) x
  union all select 'F', '"serbest" renk kaydı (Tanımlar''da olmayan, adla açılmış)', (select count(*) from public.stk_renk), count(*) from public.stk_renk where tur = 'serbest' and aktif
  union all select 'F', '"serbest" ölçü kaydı (Tanımlar''da olmayan, adla açılmış)', (select count(*) from public.stk_olcu), count(*) from public.stk_olcu where tur = 'serbest' and aktif
)
select bolum, kontrol, toplam, sorunlu from e order by bolum, 2;
